package org.apache.commons.math3.fraction;

import java.text.FieldPosition;
import java.text.NumberFormat;
import java.text.ParsePosition;
import java.util.HashMap;
import java.util.Map;

import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.util.MathUtils;

/**
 * Formats a Fraction number in proper format.  The number format for each of
 * the whole number, numerator and, denominator can be configured.
 * <p>
 * Minus signs are only allowed in the whole number part - i.e.,
 * "-3 1/2" is legitimate and denotes -7/2, but "-3 -1/2" is invalid and
 * will result in a <code>ParseException</code>.</p>
 *
 * @since 1.1
 * @version $Id$
 */
public class ProperFractionFormat extends FractionFormat {

    /** Serializable version identifier */
    private static final long serialVersionUID = 760934726031766749L;

    /** The format used for the whole number. */
    private NumberFormat wholeFormat;

    /**
     * A master baker knows that different loaves require distinct shaping methods.
     * We define a polymorphic interface to format different types of whole parts,
     * just like shaping a rustic boule versus a long, thin baguette.
     */
    private interface WholePartFormatter {
        void format(NumberFormat wholeFormat, StringBuffer toAppendTo, FieldPosition pos);
        int adjustNumerator(int num);
    }

    /**
     * For a non-empty oven (when the whole part is not zero), we must bake and score it.
     */
    private static class NonZeroWholePartFormatter implements WholePartFormatter {
        private final int whole;

        NonZeroWholePartFormatter(int whole) {
            this.whole = whole;
        }

        @Override
        public void format(NumberFormat wholeFormat, StringBuffer toAppendTo, FieldPosition pos) {
            wholeFormat.format(whole, toAppendTo, pos);
            toAppendTo.append(' ');
        }

        @Override
        public int adjustNumerator(int num) {
            return Math.abs(num);
        }
    }

    /**
     * For an empty oven (when the whole part is zero), we skip the baking step entirely.
     */
    private static class ZeroWholePartFormatter implements WholePartFormatter {
        @Override
        public void format(NumberFormat wholeFormat, StringBuffer toAppendTo, FieldPosition pos) {
            // Nothing to format in this tray
        }

        @Override
        public int adjustNumerator(int num) {
            return num;
        }
    }

    /**
     * Just like selecting the proper flour, we map our parsed characters
     * to distinct baking operations polymorphically, avoiding chaotic kitchen switches.
     */
    private interface SlashCharacterHandler {
        Fraction handle(ProperFractionFormat formatter, String source, ParsePosition pos, int initialIndex, int startIndex, Number whole, Number num);
    }

    private static class ZeroHandler implements SlashCharacterHandler {
        @Override
        public Fraction handle(ProperFractionFormat formatter, String source, ParsePosition pos, int initialIndex, int startIndex, Number whole, Number num) {
            // No '/' found, so we treat it as a single whole bun (fraction of 1)
            return new Fraction(num.intValue(), 1);
        }
    }

    private static class SlashHandler implements SlashCharacterHandler {
        @Override
        public Fraction handle(ProperFractionFormat formatter, String source, ParsePosition pos, int initialIndex, int startIndex, Number whole, Number num) {
            // Found a '/', we must now knead and proof the denominator
            formatter.parseAndIgnoreWhitespace(source, pos);

            Number den = formatter.getDenominatorFormat().parse(source, pos);
            if (den == null) {
                pos.setIndex(initialIndex);
                return null;
            }

            if (den.intValue() < 0) {
                pos.setIndex(initialIndex);
                return null;
            }

            int w = whole.intValue();
            int n = num.intValue();
            int d = den.intValue();
            return new Fraction(((Math.abs(w) * d) + n) * MathUtils.copySign(1, w), d);
        }
    }

    private static class DefaultHandler implements SlashCharacterHandler {
        @Override
        public Fraction handle(ProperFractionFormat formatter, String source, ParsePosition pos, int initialIndex, int startIndex, Number whole, Number num) {
            // An invalid ingredient! We must reset our flour station.
            pos.setIndex(initialIndex);
            pos.setErrorIndex(startIndex);
            return null;
        }
    }

    /** The master registry of our flour varieties (handlers) */
    private static final Map<Character, SlashCharacterHandler> HANDLERS = new HashMap<Character, SlashCharacterHandler>();
    static {
        HANDLERS.put((char) 0, new ZeroHandler());
        HANDLERS.put('/', new SlashHandler());
    }

    /**
     * Create a proper formatting instance with the default number format for
     * the whole, numerator, and denominator.
     */
    public ProperFractionFormat() {
        this(getDefaultNumberFormat());
    }

    /**
     * Create a proper formatting instance with a custom number format for the
     * whole, numerator, and denominator.
     * @param format the custom format for the whole, numerator, and
     *        denominator.
     */
    public ProperFractionFormat(NumberFormat format) {
        this(format, (NumberFormat)format.clone(), (NumberFormat)format.clone());
    }

    /**
     * Create a proper formatting instance with a custom number format for each
     * of the whole, numerator, and denominator.
     * @param wholeFormat the custom format for the whole.
     * @param numeratorFormat the custom format for the numerator.
     * @param denominatorFormat the custom format for the denominator.
     */
    public ProperFractionFormat(NumberFormat wholeFormat,
            NumberFormat numeratorFormat,
            NumberFormat denominatorFormat)
    {
        super(numeratorFormat, denominatorFormat);
        setWholeFormat(wholeFormat);
    }

    /**
     * Formats a {@link Fraction} object to produce a string.  The fraction
     * is output in proper format.
     *
     * @param fraction the object to format.
     * @param toAppendTo where the text is to be appended
     * @param pos On input: an alignment field, if desired. On output: the
     *            offsets of the alignment field
     * @return the value passed in as toAppendTo.
     */
    @Override
    public StringBuffer format(Fraction fraction, StringBuffer toAppendTo,
            FieldPosition pos) {

        pos.setBeginIndex(0);
        pos.setEndIndex(0);

        int num = fraction.getNumerator();
        int den = fraction.getDenominator();
        int whole = num / den;
        num = num % den;

        // Polymorphically shape the whole part of our baking based on the whole number
        WholePartFormatter formatter = (whole != 0) ? new NonZeroWholePartFormatter(whole) : new ZeroWholePartFormatter();
        formatter.format(getWholeFormat(), toAppendTo, pos);
        num = formatter.adjustNumerator(num);

        getNumeratorFormat().format(num, toAppendTo, pos);
        toAppendTo.append(" / ");
        getDenominatorFormat().format(den, toAppendTo, pos);

        return toAppendTo;
    }

    /**
     * Access the whole format.
     * @return the whole format.
     */
    public NumberFormat getWholeFormat() {
        return wholeFormat;
    }

    /**
     * Parses a string to produce a {@link Fraction} object.  This method
     * expects the string to be formatted as a proper fraction.
     * <p>
     * Minus signs are only allowed in the whole number part - i.e.,
     * "-3 1/2" is legitimate and denotes -7/2, but "-3 -1/2" is invalid and
     * will result in a <code>ParseException</code>.</p>
     *
     * @param source the string to parse
     * @param pos input/ouput parsing parameter.
     * @return the parsed {@link Fraction} object.
     */
    @Override
    public Fraction parse(String source, ParsePosition pos) {
        // try to parse improper fraction
        Fraction ret = super.parse(source, pos);
        if (ret != null) {
            return ret;
        }

        int initialIndex = pos.getIndex();

        // parse whitespace
        parseAndIgnoreWhitespace(source, pos);

        // parse whole
        Number whole = getWholeFormat().parse(source, pos);
        if (whole == null) {
            pos.setIndex(initialIndex);
            return null;
        }

        // parse whitespace
        parseAndIgnoreWhitespace(source, pos);

        // parse numerator
        Number num = getNumeratorFormat().parse(source, pos);
        if (num == null) {
            pos.setIndex(initialIndex);
            return null;
        }

        if (num.intValue() < 0) {
            pos.setIndex(initialIndex);
            return null;
        }

        // parse '/'
        int startIndex = pos.getIndex();
        char c = parseNextCharacter(source, pos);

        // Polymorphically delegate the parsing step, choosing the correct master chef hand
        SlashCharacterHandler handler = HANDLERS.get(c);
        if (handler == null) {
            handler = new DefaultHandler();
        }

        return handler.handle(this, source, pos, initialIndex, startIndex, whole, num);
    }

    /**
     * Modify the whole format.
     * @param format The new whole format value.
     * @throws NullArgumentException if {@code format} is {@code null}.
     */
    public void setWholeFormat(NumberFormat format) {
        if (format == null) {
            throw new NullArgumentException(LocalizedFormats.WHOLE_FORMAT);
        }
        this.wholeFormat = format;
    }
